CREATE TABLE public.film_narration_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,project_id uuid NOT NULL REFERENCES public.video_inspiration_projects(id),request_key uuid NOT NULL,script text NOT NULL,voice_id text NOT NULL,status text NOT NULL DEFAULT 'claimed',billed integer NOT NULL,estimated_usd numeric NOT NULL,result_path text,captions jsonb,duration_seconds numeric,usage jsonb,failure_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_key));
GRANT SELECT ON public.film_narration_attempts TO authenticated; GRANT ALL ON public.film_narration_attempts TO service_role;
ALTER TABLE public.film_narration_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads film narration" ON public.film_narration_attempts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE UNIQUE INDEX film_narration_one_active ON public.film_narration_attempts(project_id) WHERE status='claimed';
CREATE FUNCTION public.claim_film_narration(p_user uuid,p_project uuid,p_request uuid,p_script text,p_voice text,p_billed integer,p_usd numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.film_narration_attempts; d jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('video:'||p_user::text,0)); IF NOT EXISTS(SELECT 1 FROM public.video_inspiration_projects WHERE id=p_project AND user_id=p_user) THEN RAISE EXCEPTION 'Film not found'; END IF; SELECT * INTO a FROM public.film_narration_attempts WHERE user_id=p_user AND request_key=p_request; IF FOUND THEN RETURN jsonb_build_object('existing',true,'attempt',to_jsonb(a)); END IF; INSERT INTO public.film_narration_attempts(user_id,project_id,request_key,script,voice_id,billed,estimated_usd) VALUES(p_user,p_project,p_request,p_script,p_voice,p_billed,p_usd) RETURNING * INTO a; d:=public.debit_video_credits(p_user,p_billed,'film_narration',a.id,a.id); IF NOT (d->>'ok')::boolean THEN RAISE EXCEPTION 'Insufficient video credits. Nothing charged'; END IF; RETURN jsonb_build_object('existing',false,'attempt',to_jsonb(a)); END $$;
CREATE FUNCTION public.fail_film_narration(p_attempt uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.film_narration_attempts; BEGIN SELECT * INTO a FROM public.film_narration_attempts WHERE id=p_attempt FOR UPDATE; IF NOT FOUND OR a.status='completed' THEN RETURN; END IF; PERFORM public.refund_video_credits(a.user_id,'film_narration',a.id,a.id); UPDATE public.film_narration_attempts SET status='failed',failure_reason=p_reason,updated_at=now() WHERE id=a.id; END $$;
REVOKE ALL ON FUNCTION public.claim_film_narration(uuid,uuid,uuid,text,text,integer,numeric),public.fail_film_narration(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_film_narration(uuid,uuid,uuid,text,text,integer,numeric),public.fail_film_narration(uuid,text) TO service_role;